<script setup>
import {computed,ref,watch} from 'vue';
import NativeOperationStatus from './NativeOperationStatus.vue';
import {nativeItems,nativeValue} from '../bot-native-data.js';
const props=defineProps({ui:{type:Object,required:true},bot:{type:Object,required:true},enabled:Boolean});const emit=defineEmits(['stop-current']);
const goalForm=ref({objective:'',maxTurns:20}),heartbeatForm=ref({prompt:'',intervalSeconds:3600}),taskForm=ref({title:'',body:'',triage:false,maxTurns:20}),taskEditor=ref(null),taskEdit=ref({}),error=ref('');
const goalContract=ref({outcome:'',verification:'',constraints:'',boundaries:'',stop_when:''}),taskPriority=ref(0),taskParents=ref([]);
const goals=computed(()=>props.ui.resource('goals')),heartbeat=computed(()=>props.ui.resource('heartbeat')),kanban=computed(()=>props.ui.resource('kanban')),detail=computed(()=>props.ui.resource('kanbanDetail'));
const goalValue=computed(()=>nativeValue(goals.value.data)),heartbeatValue=computed(()=>nativeValue(heartbeat.value.data)),tasks=computed(()=>nativeItems(kanban.value.data,['tasks','items']));
const lanes=[['ready','待处理'],['running','处理中'],['done','已完成 / 阻断']];
const active=computed(()=>props.enabled&&props.bot.control_state==='active');
const nativeRunBaseline=ref('');
function laneTasks(lane){return tasks.value.filter(task=>lane==='running'?['running','claimed','in_progress'].includes(task.status):lane==='done'?['done','completed','blocked','cancelled'].includes(task.status):!['running','claimed','in_progress','done','completed','blocked','cancelled'].includes(task.status));}
async function startGoal(){error.value='';const contract=Object.fromEntries(Object.entries(goalContract.value).filter(([,value])=>value.trim()));await props.ui.submit('goals','start',{objective:goalForm.value.objective,maxTurns:Number(goalForm.value.maxTurns),...(Object.keys(contract).length?{contract}:{})});}
async function startHeartbeat(){error.value='';await props.ui.submit('heartbeat','start',{prompt:heartbeatForm.value.prompt,intervalSeconds:Number(heartbeatForm.value.intervalSeconds)});}
async function createTask(){const workspace=props.ui.state.workspace,id=props.bot.id;const ok=await props.ui.submit('kanban','create',{...taskForm.value,maxTurns:Number(taskForm.value.maxTurns),priority:Number(taskPriority.value),parents:[...taskParents.value]});if(ok&&kanban.value.phase==='succeeded'&&props.ui.state.workspace===workspace&&props.bot.id===id){taskForm.value={title:'',body:'',triage:false,maxTurns:20};taskPriority.value=0;taskParents.value=[];}}
async function editTask(task){const workspace=props.ui.state.workspace,id=props.bot.id;if(await props.ui.read('kanbanDetail',{taskId:task.id||task.task_id})&&props.ui.state.workspace===workspace&&props.bot.id===id){const value=nativeValue(detail.value.data),row=value?.task||value||task;taskEditor.value=task.id||task.task_id;taskEdit.value={taskId:taskEditor.value,status:row.status,title:row.title||task.title||'',body:row.body||'',runId:row.current_run_id||row.run_id||row.active_run_id||'',result:row.result||'',summary:row.summary||'',reason:''};nativeRunBaseline.value=taskEdit.value.runId;}}
async function mutateTask(operation){const form=taskEdit.value;let input={taskId:form.taskId};if(operation==='edit'){if(form.status==='triage')input={...input,title:form.title,body:form.body};else if(form.status==='done'||form.status==='completed')input={...input,result:form.result,summary:form.summary};else return;}if(['complete','block'].includes(operation)){if(!Number.isInteger(Number(form.runId))||Number(form.runId)<1){error.value='请使用本次原生任务回执中的整数 Run ID。';return;}form.runId=Number(form.runId);}if(operation==='complete')input={...input,runId:form.runId,result:form.result,summary:form.summary};if(operation==='block')input={...input,runId:form.runId,reason:form.reason};const workspace=props.ui.state.workspace,id=props.bot.id;if(await props.ui.submit('kanban',operation,input)&&kanban.value.phase==='succeeded'&&props.ui.state.workspace===workspace&&props.bot.id===id)await editTask({id:form.taskId,title:form.title});}
watch(()=>[props.ui.state.workspace,props.bot.id],()=>{goalForm.value={objective:'',maxTurns:20};heartbeatForm.value={prompt:'',intervalSeconds:3600};taskForm.value={title:'',body:'',triage:false,maxTurns:20};taskEditor.value=null;taskEdit.value={};error.value='';},{immediate:true});
watch(()=>[props.ui.state.workspace,props.bot.id],()=>{goalContract.value={outcome:'',verification:'',constraints:'',boundaries:'',stop_when:''};taskPriority.value=0;taskParents.value=[];});
watch(()=>kanban.value.data,()=>{if(!taskEditor.value)return;const row=tasks.value.find(task=>(task.id||task.task_id)===taskEditor.value);if(!row)return;const next=row.current_run_id??row.run_id??row.active_run_id??'';if(!taskEdit.value.runId||taskEdit.value.runId===nativeRunBaseline.value)taskEdit.value.runId=next;nativeRunBaseline.value=next;taskEdit.value.status=row.status;});
</script>
<template>
  <div class="native-workspace"><p v-if="error" role="alert" class="native-error">{{error}}</p>
    <p class="native-help">原生状态由此 Bot 的 Hermes 管理；触发权威为紫薇。每次模型继续和工作派发仍检查启用、权限和单任务回合限制，不新增第二套重复调度。</p>
    <section class="native-section" aria-label="原生 Goals">
      <div class="native-toolbar"><div><h3>Goals 目标</h3><p class="native-help">保存目标与有限推进约束，查看实际状态和判断结果。</p></div><button class="bot-button" :disabled="!enabled||goals.loading" @click="ui.read('goals')">读取目标状态</button></div>
      <p v-if="goalValue?.status||goalValue?.state?.status">当前状态：{{goalValue.status||goalValue.state.status}} · {{goalValue.objective||goalValue.state?.objective||goalValue.goal?.objective||''}}</p><p v-if="goalValue?.reason" class="native-help">{{goalValue.reason}}</p><details v-if="goals.data" class="native-advanced"><summary>原生目标状态</summary><pre class="native-record">{{JSON.stringify(goalValue,null,2)}}</pre></details>
      <div class="native-fields native-grid"><label class="wide">目标<textarea v-model="goalForm.objective" rows="4" placeholder="完成什么、怎样核验结果"/></label><label>单次回合上限<input v-model="goalForm.maxTurns" type="number" min="1" max="100"/></label></div>
      <details class="native-advanced"><summary>目标验收约定</summary><div class="native-fields"><label v-for="[field,label] in [['outcome','预期交付'],['verification','验证方法'],['constraints','约束条件'],['boundaries','工作边界'],['stop_when','停止条件']]" :key="field">{{label}}<textarea v-model="goalContract[field]" rows="2"/></label></div></details><div class="native-actions"><button class="bot-button primary" :disabled="!enabled||ui.blocked()||!goalForm.objective.trim()" @click="startGoal">设置原生目标</button><button class="bot-button" :disabled="!active||ui.blocked()" @click="ui.submit('goals','step',{})">推进一次</button><button class="bot-button" :disabled="!enabled||ui.blocked()" @click="ui.submit('goals','pause',{})">暂停目标</button><button class="bot-button" :disabled="!active||ui.blocked()" @click="ui.submit('goals','resume',{})">恢复目标</button><button class="bot-button danger" :disabled="!enabled||ui.blocked()" @click="ui.submit('goals','stop',{})">结束原生目标</button><button v-if="goals.pending" class="bot-button danger" @click="emit('stop-current')">请求停止当前执行</button></div>
      <p v-if="goalValue?.evaluation||goalValue?.result" class="native-record">{{goalValue.evaluation||goalValue.result}}</p><NativeOperationStatus :state="goals" @poll="ui.poll('goals')" @recover="ui.recover('goals')"/>
    </section>
    <section class="native-section" aria-label="原生 Heartbeat">
      <div class="native-toolbar"><div><h3>Heartbeat 主动检查</h3><p class="native-help">电脑与客户端需在线；下一次时间以服务器权威返回为准。</p></div><button class="bot-button" :disabled="!enabled||heartbeat.loading" @click="ui.read('heartbeat')">读取主动检查状态</button></div>
      <p v-if="heartbeatValue?.status||heartbeatValue?.state?.status">当前状态：{{heartbeatValue.status||heartbeatValue.state.status}}</p><p v-if="heartbeatValue?.next_run||heartbeatValue?.nextRunAt">下次触发：{{heartbeatValue.next_run||heartbeatValue.nextRunAt}}</p><details v-if="heartbeat.data" class="native-advanced"><summary>原生主动检查状态</summary><pre class="native-record">{{JSON.stringify(heartbeatValue,null,2)}}</pre></details>
      <div class="native-fields native-grid"><label class="wide">检查内容<textarea v-model="heartbeatForm.prompt" rows="4" placeholder="检查什么、什么时候报告、没有变化时怎样处理"/></label><label>间隔（秒）<input v-model="heartbeatForm.intervalSeconds" type="number" min="60" max="86400"/></label></div>
      <div class="native-actions"><button class="bot-button primary" :disabled="!enabled||ui.blocked()||!heartbeatForm.prompt.trim()" @click="startHeartbeat">设置原生主动检查</button><button class="bot-button" :disabled="!active||ui.blocked()" @click="ui.submit('heartbeat','step',{})">执行一次检查</button><button class="bot-button" :disabled="!enabled||ui.blocked()" @click="ui.submit('heartbeat','pause',{})">暂停检查</button><button class="bot-button" :disabled="!active||ui.blocked()" @click="ui.submit('heartbeat','resume',{})">恢复检查</button><button class="bot-button danger" :disabled="!enabled||ui.blocked()" @click="ui.submit('heartbeat','stop',{})">关闭检查</button><button v-if="heartbeat.pending" class="bot-button danger" @click="emit('stop-current')">请求停止当前执行</button></div><NativeOperationStatus :state="heartbeat" @poll="ui.poll('heartbeat')" @recover="ui.recover('heartbeat')"/>
    </section>
    <section class="native-section" aria-label="原生 Kanban">
      <div class="native-toolbar"><div><h3>Kanban 原生工作板</h3><p class="native-help">读取当前 Bot 的原生数据库；领取、结果和阻断均保留精确 task/run 标识。</p></div><button class="bot-button" :disabled="!enabled||kanban.loading" @click="ui.read('kanban',{limit:100})">刷新原生看板</button></div>
      <div class="native-fields"><label>工作标题<input v-model="taskForm.title"/></label><label>工作内容<textarea v-model="taskForm.body" rows="3"/></label><div class="native-grid"><label>单次回合上限<input v-model="taskForm.maxTurns" type="number" min="1" max="100"/></label><label>原生优先级<input v-model="taskPriority" type="number"/></label><label>前置工作<select v-model="taskParents" multiple><option v-for="task in tasks" :key="task.id||task.task_id" :value="task.id||task.task_id">{{task.title||task.id}}</option></select></label><label class="inline-check"><input v-model="taskForm.triage" type="checkbox"/>创建时进入分诊</label></div></div><div class="native-actions"><button class="bot-button primary" :disabled="!enabled||ui.blocked()||!taskForm.title.trim()" @click="createTask">创建原生工作</button></div>
      <div class="native-kanban" style="margin-top:18px"><section v-for="[lane,label] in lanes" :key="lane" class="native-kanban-lane"><h4>{{label}} · {{laneTasks(lane).length}}</h4><article v-for="task in laneTasks(lane)" :key="task.id||task.task_id" class="native-list-row"><div><strong>{{task.title||task.id||task.task_id}}</strong><small>{{task.status}} · {{task.id||task.task_id}}</small><p>{{task.summary||task.body||''}}</p><div class="native-actions"><button class="bot-button" :disabled="ui.blocked()" @click="editTask(task)">详情 / 编辑</button><button class="bot-button" :disabled="!active||ui.blocked()" @click="ui.submit('kanban','dispatch',{taskId:task.id||task.task_id})">派发此工作</button></div></div></article></section></div>
      <details v-if="taskEditor" open class="native-advanced"><summary>当前原生工作 · {{taskEditor}}</summary><div class="native-fields"><label>标题<input v-model="taskEdit.title" :disabled="taskEdit.status!=='triage'"/></label><label>正文<textarea v-model="taskEdit.body" rows="3" :disabled="taskEdit.status!=='triage'"/></label><label>原生 Run ID<input v-model.number="taskEdit.runId" type="number" min="1"/></label><label>结果<textarea v-model="taskEdit.result" rows="3"/></label><label>摘要<input v-model="taskEdit.summary"/></label><label>阻断原因<input v-model="taskEdit.reason"/></label></div><div class="native-actions"><button class="bot-button" :disabled="ui.blocked()||!['triage','done','completed'].includes(taskEdit.status)" @click="mutateTask('edit')">{{taskEdit.status==='triage'?'确认分诊任务':'修订已完成结果'}}</button><button class="bot-button" :disabled="!active||ui.blocked()||taskEdit.status!=='ready'" @click="mutateTask('claim')">领取此工作</button><button class="bot-button" :disabled="ui.blocked()||!taskEdit.runId||taskEdit.status!=='running'" @click="mutateTask('complete')">提交此 Run 的完成结果</button><button class="bot-button" :disabled="ui.blocked()||!taskEdit.runId||!taskEdit.reason||taskEdit.status!=='running'" @click="mutateTask('block')">提交阻断</button><button class="bot-button" :disabled="ui.blocked()||taskEdit.status!=='blocked'" @click="mutateTask('unblock')">解除阻断</button><button class="bot-button" @click="taskEditor=null">关闭详情</button></div></details><NativeOperationStatus :state="detail"/><NativeOperationStatus :state="kanban" @poll="ui.poll('kanban')" @recover="ui.recover('kanban')"/>
    </section>
  </div>
</template>
